query:
*[_type=="blogPost" && references(*[_type=="blogCategory" && slug.current=="engineering"]._id) && hidePost != true] | order(date desc) [0...100] {
  "slug": slug.current, "title": title, "date": date, "synopsis": synopsis,
  "author": author, "image": hero.image.asset->url, "categories": categories[]->name
}
